package org.apache.commons.math.optimization.univariate;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.math.FunctionEvaluationException;
import org.apache.commons.math.MaxIterationsExceededException;
import org.apache.commons.math.analysis.UnivariateRealFunction;
import org.apache.commons.math.exception.MaxIterationsExceededException;
import org.apache.commons.math.exception.NotStrictlyPositiveException;
import org.apache.commons.math.optimization.GoalType;
import org.apache.commons.math.optimization.univariate.GoalType.MAXIMIZE;
import org.apache.commons.math.optimization.univariate.GoalType.MINIMIZE;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

/**
 * Unit tests for BrentOptimizer constructor.
 * Since the constructor only sets internal state, we verify the state by 
 * executing optimization tasks that rely on those default parameters.
 */
public class BrentOptimizer_BrentOptimizer_TriageGen1Test {

    @Test
    public void testConstructorAndOptimizeMinimization() throws MaxIterationsExceededException {
        // Given a simple convex function f(x) = (x - 2)^2, minimum is at x = 2
        BrentOptimizer optimizer = new BrentOptimizer();
        UnivariateRealFunction function = x -> Math.pow(x - 2.0, 2);

        // When finding the minimum in range [0, 5]
        double result = optimizer.optimize(function, MINIMIZE, 0.0, 5.0);

        // Then the result should be approximately 2.0
        // The constructor sets absolute accuracy to 1E-10, so we use a tight delta
        assertEquals(2.0, result, 1E-7);
    }

    @Test
    public void testConstructorAndOptimizeMaximization() throws MaxIterationsExceededException {
        // Given a simple concave function f(x) = -(x - 3)^2, maximum is at x = 3
        BrentOptimizer optimizer = new BrentOptimizer();
        UnivariateRealFunction function = x -> -Math.pow(x - 3.0, 2);

        // When finding the maximum in range [0, 5]
        double result = optimizer.optimize(function, MAXIMIZE, 0.0, 5.0);

        // Then the result should be approximately 3.0
        assertEquals(3.0, result, 1E-7);
    }

    @Test
    public void testConstructorAndOptimizeWithStartValue() throws MaxIterationsExceededException {
        // Given a simple convex function f(x) = (x - 1)^2, minimum is at x = 1
        BrentOptimizer optimizer = new BrentOptimizer();
        UnivariateRealFunction function = x -> Math.pow(x - 1.0, 2);

        // When finding the minimum in range [0, 5] with a specific start value
        double result = optimizer.optimize(function, MINIMIZE, 0.0, 5.0, 4.0);

        // Then the result should be approximately 1.0
        assertEquals(1.0, result, 1E-7);
    }

    @Test(expected = MaxIterationsExceededException.class)
    public void testConstructorAndMaxIterationsExceeded() throws MaxIterationsExceededException {
        // To test the iteration limit set by the constructor (100), 
        // we use a function that oscillates heavily or is non-convergent within the limit.
        // However, since we can't easily change the private maxIterations via constructor,
        // we simulate a scenario that consumes many iterations.

        BrentOptimizer optimizer = new BrentOptimizer();

        // A function that is very flat or has many local minima can trigger high iteration counts
        // But a more reliable way to trigger MaxIterationsExceededException in a unit test 
        // for a constructor-only test is to provide a function that doesn't converge easily.
        // Using a very high precision requirement vs a function with noise:
        UnivariateRealFunction noisyFunction = x -> Math.sin(1.0 / (x + 0.0000001));

        // This might not always throw depending on the range, but it tests the path.
        // For the purpose of this triage test, we assume the constructor's 100 iterations is small.
        optimizer.optimize(noisyFunction, MINIMIZE, 0.00001, 1.0);
    }
}
